import {workItems,equipmentReceipt,flowSteps,flowStep,flowSections,planningUpdate,recordGaps,purchaseNeeds,closeoutLabel} from './workflow-model.js';
'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),usd=x=>x===null||x===undefined?'Unconfirmed':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(x/100),date=x=>x?new Date(x).toLocaleString():'Unscheduled';
let data,events=[],selected=new URLSearchParams(location.search).get('event'),tab='events',prep=null,dirtyForm=null,showAllDetails=false,viewStep=null;
async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json'}});const d=await r.json();if(r.status===401){location.replace('/admin/login.html?next='+encodeURIComponent(location.pathname+location.search));throw Error('Sign in required.');}if(!r.ok)throw Error(d.error||'Request failed.');return d;}
const state=()=>data.state,ev=()=>state().events[selected]||structuredClone(data.eventTemplate),eventDoc=()=>events.find(x=>x.id===selected),field=(label,name,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`,dollarInput=(name,cents)=>`<input aria-label="${esc(name)}" name="${esc(name)}" type="number" min="0" step="0.01" value="${cents===null?'':cents/100}" placeholder="Unknown">`,check=(label,name,value)=>`<label class="checkline"><input name="${name}" type="checkbox" ${value?'checked':''}>${esc(label)}</label>`;
const cents=x=>x===''?null:Math.round(Number(x)*100),nullable=x=>x===''?null:Number(x),localTime=x=>{if(!x)return '';const d=new Date(x);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);},iso=x=>x?new Date(x).toISOString():'';
function notify(m){$('#message').textContent=m;}
function clean(){if(dirtyForm){notify('Save the form you are editing before switching or making another change.');return false;}return true;}
let commandPending=false;
async function command(action,payload,form=null){if(commandPending)return;if(dirtyForm&&dirtyForm!==form){notify('Save the current form first.');return;}const controls=form?[...form.querySelectorAll('button')]:[];commandPending=true;for(const b of controls)b.disabled=true;const scrollY=window.scrollY;try{data=await api('/api/admin/operations',{method:'POST',body:JSON.stringify({version:state().version,action,payload})});dirtyForm=null;if(prep)prep.operationsVersion=state().version;if(action==='advance'||action==='reopen')viewStep=null;render();window.scrollTo(0,scrollY);notify('Saved. Shared operations updated.');}catch(e){for(const b of controls)b.disabled=false;notify(e.message);}finally{commandPending=false;}}
async function load(){if(!clean())return;try{data=await api('/api/admin/operations');events=[];let offset=0;do{const r=await api('/api/admin/inquiries?offset='+offset);events.push(...r.items);offset=r.nextOffset;}while(offset!==null);if(selected&&!events.some(e=>e.id===selected))selected=null;if(selected)prep=await api('/api/admin/inquiries/'+selected+'/preparation');render();notify('');}catch(e){notify(e.message);}}
function eventName(id){const d=events.find(x=>x.id===id);return d?.payload.details.company||d?.payload.details.name||id;}
function metric(title,value,note){return `<div class="ops-card"><span class="kicker">${title}</span><strong class="metric">${value}</strong><small>${note}</small></div>`;}
function render(){document.querySelector('.ops').classList.toggle('event-mode',tab==='events'&&!!selected);$('#discard').hidden=!dirtyForm;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.tab===tab));$('#content').innerHTML=tab==='inventory'?inventoryView():tab==='staff'?staffView():tab==='activity'?activityView():selected?eventView():overview();if(tab==='events'&&selected)focusStage();if(tab==='events'&&selected&&ev().stage===8)document.querySelectorAll('#content form input,#content form select,#content form textarea,#content form button').forEach(x=>x.disabled=true);}
function allEventsOverview(){return `<div class="ops-grid">${events.map(d=>{const e=state().events[d.id]||data.eventTemplate;return `<button class="ops-card ops-event" data-open-event="${d.id}"><span class="kicker">${esc(data.stages[e.stage]||'Completed')}</span><h3>${esc(eventName(d.id))}</h3><span>${d.payload.guests} guests · ${esc(d.payload.details.date||'Date undecided')}</span><span>${esc(e.owner||'Owner needed')}</span><small>${e.stage<8?esc(data.checklist[e.stage].find((_,i)=>!e.tasks[e.stage][i].done)||'Ready to advance'):esc(closeoutLabel(data.financials[d.id]))}${e.due?' · Due '+esc(date(e.due)):''}</small></button>`;}).join('')}</div>`;}
function overview(){const items=workItems(events,state(),data.eventTemplate),open=events.filter(d=>(state().events[d.id]?.stage??0)<8);return `<div class="today-heading"><div><p class="kicker">YOUR WORK QUEUE</p><h2>Today & next actions</h2><p class="muted">${esc(new Date().toLocaleDateString(undefined,{dateStyle:'full'}))} · ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Undated events stay in planning.</p></div></div><div class="ops-grid">${metric('Open events',open.length,'Planning through reconciliation')}${metric('Return loads',state().reservations.filter(r=>r.status==='dispatched').length,'Currently away from the office')}${metric('Need attention',items.length,'Prioritized below')}${metric('Stock to count',state().inventory.length?state().inventory.filter(x=>x.quantity===null).length:state().openingStockZero?0:'Not set up','Unknown counts cannot be reserved')}</div><div class="work-queue">${items.map(x=>`<button class="work-item" data-open-event="${esc(x.id)}"><span><span class="kicker">${esc(x.label)}</span><strong>${esc(eventName(x.id))}</strong><small>${esc(x.eventDate||'Date undecided')}${x.due?' · Deadline '+esc(date(x.due)):''}</small><small>${esc(x.reasons.slice(1).join(' · '))}</small></span><span class="work-action">${esc(x.action)} →</span></button>`).join('')||'<p class="ops-card">No flagged actions. Review your events below for upcoming work.</p>'}</div><h2>All events</h2><label>Find an event<input type="search" id="event-search" placeholder="Search name, owner, date or stage"></label><label>Event status<select id="event-filter"><option value="all">All events</option><option value="open">Open events</option><option value="closed">Completed events</option></select></label><div id="all-events">${allEventsOverview()}</div>`;}
function focusStage(){const stage=ev().stage,step=viewStep??flowStep(stage);document.querySelector('.ops').classList.add('event-mode');const sections=[...document.querySelectorAll('#content > details:not(.client-brief)')];const keys=['finance','planning','staff','stock','orders',...(stage===8?[]:['supplier']),'activity'];sections.forEach((el,i)=>{el.dataset.section=keys[i];const relevant=flowSections[step].includes(keys[i]);el.hidden=stage!==8&&!showAllDetails&&!relevant;el.open=stage!==8&&relevant;});const finance=sections[0];finance.querySelector('summary').textContent=step===0?'Confirm owner & agreed price':'Event budget & reconciliation';const form=finance.querySelector('form'),table=form.querySelector('.ops-table');if(table){const breakdown=document.createElement('details');breakdown.innerHTML='<summary>View cost breakdown</summary>';table.before(breakdown);let node=table;while(node&&node.tagName!=='BUTTON'){const next=node.nextElementSibling;breakdown.append(node);node=next;}}
if(ev().inventoryCosting){for(const name of ['stockUsed','leftover']){const input=finance.querySelector('[name='+name+']');if(input)input.closest('label').hidden=true;}}const plan=sections.find(x=>x.dataset.section==='planning');if(plan){plan.querySelector('summary').textContent=step===1?'Menu, quantities & equipment':step===2?'Check the outgoing equipment':'Service plan & packing';}
if(step===4){const stock=sections.find(x=>x.dataset.section==='stock');if(stock){stock.querySelector('summary').textContent='Receive at office';const forms=[...stock.querySelectorAll('.return-form')];const intro=document.createElement('p');intro.className='alert';intro.textContent=forms.length?forms.length+' load(s) awaiting receipt. Check quantities and condition, then receive each item.':'No dispatched loads awaiting receipt. Release unused reservations before closing.';stock.querySelector('summary').after(intro);for(const form of forms)intro.after(form.closest('section'));const other=document.createElement('details');other.innerHTML='<summary>Ingredient needs & new reservations</summary>';[...stock.children].filter(x=>!['SUMMARY','SECTION'].includes(x.tagName)&&x!==intro).forEach(x=>other.append(x));stock.append(other);}}
const order=flowSections[step];const footer=$('#flow-next');for(const key of order){const el=sections.find(x=>x.dataset.section===key);if(el)footer.before(el);}for(const el of sections.filter(x=>!order.includes(x.dataset.section)))footer.before(el);
 // Wizard presentation: one card per step — header (what this step needs), the step's sections, then checkpoints and navigation.
 if(stage!==8&&!showAllDetails){const e=ev(),current=flowStep(stage),card=document.createElement('section');card.className='wizard-card';card.dataset.step=step;footer.before(card);const head=document.createElement('div');head.className='wizard-head';const intro=document.querySelector('.flow-intro');if(intro)head.append(intro);const total=data.checklist[stage].length,done=e.tasks[stage].filter(t=>t.done).length;const status=document.createElement('p');status.className='wizard-status';status.textContent=step<current?'Completed step · records stay editable':step>current?'Upcoming step · preview and prepare; the event advances from the current step':done===total?'All checkpoints confirmed · continue when the records below are saved':`${done} of ${total} checkpoints confirmed`;head.append(status);card.append(head);const body=document.createElement('div');body.className='wizard-body';for(const key of order){const el=sections.find(x=>x.dataset.section===key);if(el)body.append(el);}card.append(body);const nav=document.createElement('div');nav.className='wizard-nav';nav.innerHTML=step>0?`<button type="button" class="secondary" data-flow-step="${step-1}">← Back to ${esc(flowSteps[step-1])}</button>`:'';if(nav.innerHTML)footer.prepend(nav);card.append(footer);}
}
function filterEvents(){const query=$('#event-search').value.toLowerCase(),filter=$('#event-filter').value;document.querySelectorAll('#all-events [data-open-event]').forEach(card=>{const closed=(state().events[card.dataset.openEvent]?.stage??0)===8;card.hidden=!card.textContent.toLowerCase().includes(query)||(filter==='open'&&closed)||(filter==='closed'&&!closed);});}
function eventView(){const e=ev(),d=eventDoc(),f=data.financials[selected],closed=e.stage===8,current=flowStep(e.stage),step=viewStep??current;const gaps=recordGaps(e,f,state().reservations.filter(x=>x.eventId===selected));const pending=closed?[]:data.checklist[e.stage].filter((_,i)=>!e.tasks[e.stage][i].done);return `<button data-overview>← All events</button><div class="event-title"><p class="kicker">EVENT WORKSPACE</p><h2>${esc(eventName(selected))}</h2></div><a class="prep-link" href="/admin/event.html?event=${encodeURIComponent(selected)}">Edit event details →</a> <a class="prep-link" href="/admin/proposal.html?event=${encodeURIComponent(selected)}">Create proposal →</a>${e.agreementNeedsReview?'<p class="notice">Event scope changed. Review and accept a revised proposal; previous agreed figures are retained for reference.</p>':''}${e.preparationNeedsReview?`<p class="notice">Preparation changed. <a class="prep-link" href="/admin/preparation.html?event=${encodeURIComponent(selected)}">Open event preparation</a> to review and confirm the saved menu and quantities before this event can advance.</p>`:''}${e.acceptedProposalRevision?`<p class="notice">Accepted proposal r${e.acceptedProposalRevision} · Revenue before tax ${usd(e.revenueCents)} · Sales tax ${usd(e.salesTaxCents)} · Client total ${usd(e.invoiceTotalCents)}</p>`:''}${e.acceptedScope?`<details class="client-brief"><summary>Accepted service brief · proposal r${e.acceptedProposalRevision}</summary><p>Load-in ${esc(e.acceptedScope.loadIn)} · Departure ${esc(e.acceptedScope.departure)}</p><p style="white-space:pre-wrap">${esc(e.acceptedScope.scope)}</p><p style="white-space:pre-wrap">${esc(e.acceptedScope.terms)}</p><p>Deposit ${usd(e.acceptedScope.depositCents)} due ${esc(e.acceptedScope.depositDue)} · Balance ${usd(e.acceptedScope.balanceCents)} due ${esc(e.acceptedScope.balanceDue)}</p></details>`:''}<div class="event-summary"><span><strong>${d.payload.guests} guests</strong>${esc(d.payload.details.date||'Date to confirm')}</span><span><strong>${esc(d.payload.details.venue||'Venue to confirm')}</strong>${esc(d.payload.details.startTime||'Time to confirm')}</span><span><strong>${usd(f?.plannedComplete?f.planned:null)}</strong>${f?.plannedComplete?'Planned event cost':'Cost incomplete'+(f?.planned?' · '+usd(f.planned)+' entered':'')}</span><span><strong>${usd(f?.profit)}</strong>Actual event profit</span></div><nav class="flow-steps" aria-label="Event steps">${flowSteps.map((name,i)=>`<button data-flow-step="${i}" aria-current="${i===step?'step':'false'}" data-upcoming="${!closed&&i>current}" title="${closed||i<current?'Review this completed step':i===current?'Current step':'Preview this upcoming step; the event advances with Continue'}"><span>${closed||i<current?'✓':i+1}</span>${esc(name)}<small>${closed||i<current?'Completed':i===current?'Current step':'Upcoming'}</small></button>`).join('')}</nav><section class="flow-intro"><p class="kicker">STEP ${step+1} OF 5</p><h2>${esc(flowSteps[step])}</h2><p>${['Review the client details, name the event owner and confirm the agreed price.','Review the selected menu, calculate quantities, assign staff and reserve what you have.','Arrange supplier needs, check equipment into the outgoing load and dispatch it.','Keep the service plan handy. Confirm arrival and setup, then service and cleanup.','Receive the equipment, count usable leftovers and reconcile actual hours and costs.'][step]}</p>${step!==current&&!closed?'<p class="alert">You are reviewing another step. The event remains at '+esc(data.stages[e.stage])+'.</p>':''}</section><details class="client-brief"><summary>Client & venue details · ${esc(d.labels.menus.join(', ')||'Menu undecided')}</summary><p>${esc(d.payload.details.name)} · ${esc(d.payload.details.email)}</p><p>${esc(d.payload.details.venue||'Venue unconfirmed')} · ${esc(d.payload.details.city)} · ${esc(d.payload.details.timezone||'Timezone unconfirmed')}</p><p>Access / restrictions: ${esc(d.payload.details.restrictions||'Not entered')}</p><p>Planning deadline: ${esc(date(e.due))}</p><a href="/admin">Open inquiry desk for original client details ↗</a></details><div class="inline-actions"><button data-show-details aria-expanded="${showAllDetails}">${showAllDetails?'Focus on this step':'Show all event details'}</button></div>${financialForm(e,f)+planningForm()+staffingView(e)+reservationView()+ordersView(e)+(closed?'':supplierView())}<details><summary>Event activity</summary>${activityView(selected)}</details><section id="flow-next" class="ops-card"><p class="kicker">${closed?'EVENT COMPLETED':step===current?'NEXT ACTION':'CURRENT PROGRESS'}</p><h3>${esc(data.stages[e.stage]||closeoutLabel(f))}</h3>${closed?'<p>Equipment return complete. Review costs and client payments below.</p><button data-reopen>Reopen reconciliation</button>':step!==current?'<button data-current-step>Return to current step →</button>':`${gaps.length?'<div class="alert"><strong>Still needed</strong><ul>'+gaps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':''}<p>${pending.length?pending.length+' checkpoint(s) left. Complete the work above, then confirm below.':'Checkpoints confirmed. Continue when the required records are saved.'}</p>${e.tasks[e.stage].map((t,i)=>`<label class="task"><input type="checkbox" data-task="${i}" ${t.done?'checked':''}><span>${esc(data.checklist[e.stage][i])}<small>${t.done?esc(t.by)+' · '+esc(date(t.at)):'Needs confirmation'}</small></span></label>`).join('')}<button data-advance>${e.stage===7?'Close event':'Continue'} →</button><p class="muted">Saved costs, staffing and load records are checked before advancing. Nothing is sent to clients or suppliers.</p>`}</section>`;}
function planningForm(){if(!prep?.plan)return '<details><summary>Preparation unavailable</summary><p>Refresh to load the saved preparation plan.</p></details>';const p=prep.plan,x=prep.summary;return `<details><summary>Menu, quantities & equipment</summary><p><strong>${esc(eventDoc().labels.menus.join(', ')||'Menu to confirm')}</strong></p><p>${x.totalDrinks??'Unknown'} planned drinks · ${p.machines} machines · ${x.packed}/${x.equipment.length} equipment lines packed.</p><p class="${x.complete?'muted':'alert'}">${x.complete?'Measured quantities available. Confirm actual stock and supplier pack sizes.':'Incomplete plan: confirm menu, recipes and drink quantities before purchasing.'}</p>${(x.catalogWarnings||[]).map(w=>`<p class="alert">${esc(w)}</p>`).join('')}<form id="flow-prep" class="ops-form"><div class="ops-grid">${field('Drinks per guest','drinks',p.drinksPerGuest??'','number','min="0.1" max="20" step="0.1"')}${field('Buffer %','buffer',p.bufferPercent,'number','min="0" max="100"')}${field('360 machines','machines',p.machines,'number',`min="${x.minimumMachines}" max="1000" required`)}</div>${check('Client menu confirmed','menuConfirmed',p.menuConfirmed)}<details><summary>Review recipes & demand split (${p.recipes.length})</summary>${p.recipes.map((r,i)=>`<div class="ops-card" data-flow-recipe="${i}"><h3>${esc(r.name)}</h3><p>${x.servings[i]?.count??'Unknown'} planned servings</p>${r.reviewNote?`<p class="alert">${esc(r.reviewNote)}</p>`:''}${field('Demand weight','share-'+i,r.share,'number','min="0" max="100" step="0.1" required')}<label>Measured ingredients · name | amount | unit<textarea name="ingredients-${i}" rows="4">${esc(r.ingredients.map(z=>[z.name,z.amount,z.unit].join(' | ')).join('\n'))}</textarea></label>${check('Measurements confirmed','confirmed-'+i,r.confirmed)}</div>`).join('')}</details><details${(viewStep??flowStep(ev().stage))===2?' open':''}><summary>Equipment needed & packing</summary><p class="muted">Changing the machine count resets packing checks. Packed items still need an inventory reservation and dispatch record.</p>${x.equipment.map(q=>`<div class="packing-line"><span><strong>${esc(q.name)}</strong><small>${q.minimum===null?'Confirm quantity':q.minimum+' minimum'}</small></span>${field('Quantity','equipment-'+q.id,q.quantity??'','number',`min="${q.minimum??0}" max="10000" step="1" ${q.id==='machines'?'readonly':''}`)}${check('Packed','packed-'+q.id,q.packed)}</div>`).join('')}</details><button>Save quantities & packing</button></form><details><summary>Ingredient requirements & reference costs</summary>${shortagesView()}<p>${usd(x.costs.knownPurchaseCents)} ${x.costs.complete?'estimated whole-pack purchases':'known purchase subtotal — incomplete'}. Before office stock deductions, tax and delivery.</p><a href="/admin/preparation.html?event=${selected}">Advanced price overrides & preparation export ↗</a></details></details>`;}
function financialForm(e,f){return `<details${[1,7].includes(e.stage)?' open':''}><summary>Owner, budget & financial reconciliation</summary><form id="event-form" class="ops-form"><div class="ops-grid">${field('Event owner','owner',e.owner,'text','required maxlength="120"')}${field('Next action deadline (your device timezone)','due',localTime(e.due),'datetime-local')}${field('Agreed revenue before sales tax, USD','revenue',e.revenueCents===null?'':e.revenueCents/100,'number','min="0" step="0.01"')}${field('Target margin %','target',e.targetMargin,'number','min="0" max="100" step="0.1"')}</div><label>Internal event notes<textarea name="notes" maxlength="2000">${esc(e.notes)}</textarea></label><div class="ops-table"><table><thead><tr><th>Cost category</th><th>Planned USD</th><th>Actual paid USD</th><th>Invoice / reference / notes</th></tr></thead><tbody>${e.expenses.map((x,i)=>`<tr><th>${esc(x.name)}</th><td>${dollarInput('planned-'+i,x.plannedCents)}</td><td>${dollarInput('actual-'+i,x.actualCents)}</td><td><input aria-label="${esc(x.name)} reference" name="note-${i}" value="${esc(x.note)}" maxlength="500"></td></tr>`).join('')}<tr><th>Staff (calculated below)</th><td>${usd(f?.plannedStaff)}</td><td>${usd(f?.actualStaff)}</td><td>Planned and actual hours × saved staff rate</td></tr></tbody></table></div><div class="ops-grid">${field('Existing office stock sent: cost value USD','stockUsed',e.stockUsedCents===null?'':e.stockUsedCents/100,'number','min="0" step="0.01"')}${field('Reusable stock returned: cost value USD','leftover',e.leftoverCents===null?'':e.leftoverCents/100,'number','min="0" step="0.01"')}</div>${e.inventoryCosting?`<p class="alert">Inventory costs are calculated from dispatch and return records: ${usd(f?.ledger?.issuedCents)} sent, ${usd(f?.ledger?.returnedCents)} returned; equipment losses ${usd(f?.ledger?.equipmentLossCents)}. Purchase cash paid ${usd(f?.ledger?.purchasePaidCents)}; supplier balance ${usd(f?.ledger?.purchaseUnpaidCents)}. Do not enter received inventory invoices again in expense rows. Equipment capital purchases are cash outlay; enter event depreciation/rental separately.</p>`:''}<p class="muted">Blank costs remain unknown. Enter 0 only when confirmed not applicable. ${e.inventoryCosting?'Cash outlay includes linked inventory payments. Event cost uses non-inventory expenses plus stock issued minus reusable stock returned; whole inventory purchases are not charged again.':'Actual cash paid excludes existing stock. Event cost = cash paid + existing stock sent − reusable stock returned.'} Value inventory at cost, not retail; do not subtract reusable rentals twice. Taxes collected for remittance are excluded from revenue; nonrecoverable purchase taxes belong in costs.</p>${check('Staffing plan reviewed (including events with no staff)','staffingConfirmed',e.staffingConfirmed)}${check('All actual staff hours reviewed','actualHoursConfirmed',e.actualHoursConfirmed)}<p>Cash paid: ${usd(f?.cash)} known subtotal · Consumed cost: ${usd(f?.consumed)} ${f?.actualComplete?'confirmed':'known subtotal'} · Target cost budget: ${usd(f?.budget)} · Planned profit: ${usd(f?.plannedProfit)}</p><button>Save event & finances</button></form>${paymentForm(e,f)}</details>`;}
function staffingView(e){return `<details><summary>Staff assignments & hours (${e.staffing.length})</summary><p class="muted">Times use your device timezone (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}). Include travel, setup, service, cleanup and office return. Overlapping assignments are blocked. Hour totals are entered separately to allow breaks. Saved rates do not change when directory rates change.</p>${e.staffing.map(x=>`<form class="assignment ops-form" data-id="${x.id}"><h3>${esc(x.name)} · ${x.internal||x.rateCents===0?'Barsys team · no labor cost':usd(x.rateCents)+'/hour'}</h3><input type="hidden" name="staffId" value="${x.staffId}"><div class="ops-grid">${field('Role','role',x.role)}${field('Start','start',localTime(x.start),'datetime-local','required')}${field('End','end',localTime(x.end),'datetime-local','required')}${field('Planned paid hours','plannedHours',x.plannedHours,'number','min="0" max="500" step="0.25" required')}${field('Actual paid hours','actualHours',x.actualHours??'','number','min="0" max="500" step="0.25"')}</div><button>Save assignment / hours</button>${x.actualHours===null?`<button type="button" data-unassign="${x.id}">Remove assignment</button>`:''}</form>`).join('')}<form id="assign-form" class="ops-form"><h3>Add staff assignment</h3><label>Staff<select name="staffId" required><option value="">Choose from directory</option>${state().staff.filter(x=>x.active).map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.internal?'Barsys team · no labor cost':usd(x.rateCents)+'/hour'}</option>`).join('')}</select></label><div class="ops-grid">${field('Role','role','','text','required')}${field('Start','start','','datetime-local','required')}${field('End including office return','end','','datetime-local','required')}${field('Planned paid hours','plannedHours','','number','min="0" max="500" step="0.25" required')}</div><button>Assign staff</button></form></details>`;}
function shortagesView(){const rows=prep?.summary.ingredients||[];return `<h3>Ingredient needs against counted stock</h3><p class="muted">Matches exact ingredient name and unit. Unmatched bottle sizes require manual conversion; unknown stock is never zero. Confirm recipes before purchasing. Current-event reserved or dispatched quantities count toward coverage.</p><div class="ops-table"><table><thead><tr><th>Ingredient</th><th>Needed</th><th>Allocated</th><th>Unreserved stock</th><th>Shortage</th></tr></thead><tbody>${rows.map(r=>{const matches=state().inventory.filter(x=>x.kind==='consumable'&&x.unit===r.unit&&x.name.toLowerCase()===r.name.toLowerCase()),known=matches.length?matches.every(x=>x.quantity!==null):!!state().openingStockZero,ids=matches.map(x=>x.id),alloc=state().reservations.filter(x=>ids.includes(x.itemId)&&x.eventId===selected&&['reserved','dispatched'].includes(x.status)).reduce((n,x)=>n+x.quantity,0),free=matches.reduce((n,x)=>n+(x.condition==='ready'?(x.quantity??0)-state().reservations.filter(a=>a.itemId===x.id&&a.status==='reserved').reduce((v,a)=>v+a.quantity,0):0),0);return `<tr><th>${esc(r.name)}</th><td>${r.amount} ${esc(r.unit)}</td><td>${alloc}</td><td>${known?free:'Unknown / unmatched'}</td><td>${known?Math.max(0,r.amount-free-alloc).toFixed(3):'Count / match first'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function reservationView(){const list=state().reservations.filter(r=>r.eventId===selected);return `<details><summary>Reserve, dispatch & receive stock (${list.filter(x=>!['released','returned'].includes(x.status)).length} open)</summary>${shortagesView()}<p class="muted">Counts use the item's unit exactly. Enter bottle fractions for partial bottles, or track liquids in ml; do not mix units. Each machine or iPad needs its own labelled equipment entry. Return conditions block rebooking until ready.</p>${list.map(r=>{const item=state().inventory.find(x=>x.id===r.itemId);return `<section class="ops-card"><h3>${esc(item.name)} · ${r.quantity} ${esc(item.unit)}</h3><p>${esc(r.status)} · ${esc(date(r.start))} → ${esc(date(r.end))}</p>${r.status==='reserved'?`<button data-dispatch="${r.id}">Mark dispatched</button> <button data-release="${r.id}">Release reservation</button>`:r.status==='dispatched'?`<form class="return-form ops-form" data-id="${r.id}">${item.kind==='equipment'?`<div class="return-actions">${[['ready','Returned & ready'],['cleaning','Needs cleaning'],['charging','Needs charging'],['repair','Needs repair'],['missing','Missing']].map(([action,label])=>`<button type="button" data-return-preset="${action}">${label}</button>`).join('')}</div><small>Choose a condition to fill the receipt. Nothing changes until you press Receive at office.</small>`:''}<div class="ops-grid">${field('Usable quantity returned','returned','','number','required min="0" step="0.001"')}${field('Lost / discarded quantity','lost',0,'number','required min="0" step="0.001"')}<label>Condition<select name="condition">${['ready','cleaning','charging','repair'].map(x=>`<option>${x}</option>`).join('')}</select></label></div>${field('Return / damage notes','note','','text','maxlength="500"')}<p class="muted">For consumables, the remainder is recorded as consumed. All equipment must be returned or recorded lost.</p><button>Receive at office</button></form>`:r.status==='returned'?`<p>Returned ${r.returned}; lost ${r.lost}; consumed ${r.consumed}. Received by ${esc(r.receivedBy)}.</p><p>${esc(r.note)}</p>`:''}</section>`;}).join('')}<form id="reserve-form" class="ops-form"><h3>Reserve counted inventory</h3><label>Item<select name="itemId" required><option value="">Select stock or equipment</option>${state().inventory.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.quantity===null?'Unknown stock':x.quantity+' '+esc(x.unit)+' on hand'} · ${esc(x.condition)}</option>`).join('')}</select></label><div class="ops-grid">${field('Quantity','quantity','','number','required min="0.001" step="0.001"')}${field('Office departure','start','','datetime-local','required')}${field('Expected office return','end','','datetime-local','required')}</div><button>Reserve for this event</button></form></details>`;}
function ordersView(e){return `<details><summary>Supplier orders & receipts (${(e.orders||[]).length})</summary>${receiptForm(e)}<p class="muted">Track supplier replies and receipts here. Status changes do not send messages or place orders. Receive inventory using the form above. Enter only non-inventory expenses separately in financial reconciliation; do not enter the same purchase twice.</p>${[...(e.orders||[]),{id:'',supplier:'Astor Wines & Spirits',status:'draft',reference:'',amountCents:null,notes:''}].map(x=>`<form class="order-form ops-form ops-card" data-id="${x.id}"><h3>${x.id?'Supplier record':'Add supplier record'}</h3><div class="ops-grid">${field('Supplier','supplier',x.supplier,'text','required maxlength="200"')}${field('Order / invoice reference','reference',x.reference,'text','maxlength="200"')}<label>Status<select name="status">${['draft','requested','confirmed','received','cancelled'].map(v=>`<option ${v===x.status?'selected':''}>${v}</option>`).join('')}</select></label>${field('Quoted / invoiced USD','amount',x.amountCents===null?'':x.amountCents/100,'number','min="0" step="0.01"')}</div><label>Products, delivery or receipt notes<textarea name="notes" maxlength="2000">${esc(x.notes)}</textarea></label><button>Save supplier record</button></form>`).join('')}</details>`;}
function supplierView(){const d=eventDoc(),c=prep?.summary.costs,needs=purchaseNeeds(c?.rows||[],state(),selected);const rows=needs.purchases.filter(x=>{try{return new URL(x.url).hostname==='www.astorwines.com';}catch{return false;}})||[];const text=['To: vpagan@astorwines.com','Subject: Quote request — '+eventName(selected),'','Please confirm availability, current pricing, taxes and delivery for this event. This is a quote request, not an order authorization.','Event: '+eventName(selected),'Date: '+(d.payload.details.date||'To confirm'),'Guests: '+d.payload.guests,'Venue: '+(d.payload.details.venue||'To confirm')+', '+d.payload.details.city,'Delivery date / address / access: PLEASE COMPLETE BEFORE SENDING','','Requested products:',...rows.map(x=>`${x.product} — ${x.packs} packs of ${x.packAmount} ${x.unit}; reference ${usd(x.priceCents)} each\n${x.url}`),'',`Planning status: ${c?.complete&&!needs.unresolved.length?'Measured estimate':'INCOMPLETE: confirm all recipes, prices and yields'}.`,`Quantities deduct counted ready office stock and current-event allocations. Unknown stock, missing recipes/prices/yields need review. Incoming orders are not counted until received. Confirm products, sizes and final quantities before sending.`,'Please reply with a quote and proposed delivery arrangements. Thank you.'].join('\n');return `<details><summary>Astor supplier quote draft</summary><p>To: <strong>vpagan@astorwines.com</strong>. ${rows.length} matched Astor products. Only Astor product references are listed; other suppliers and unpriced ingredients remain in the preparation page.</p><p class="alert">Review quantities against office stock and complete delivery details. Nothing is sent automatically. Draft edits are temporary; download before leaving this event.</p><textarea id="supplier-draft" rows="16" style="width:100%">${esc(text)}</textarea><div class="inline-actions"><button data-email ${rows.length?'':'disabled'}>Open email draft</button><button data-download-draft>Download draft text</button></div></details>`;}
function countButtons(x){const t=data.inventoryTemplates.find(t=>t.name.toLowerCase()===x.name.toLowerCase()&&t.unit===x.unit),amount=x.kind==='equipment'?1:t?.packAmount||1;return `<div class="inline-actions"><button type="button" data-count-adjust="${-amount}">− ${amount===1?'1 '+esc(x.unit):'1 matching pack'}</button><button type="button" data-count-adjust="${amount}">+ ${amount===1?'1 '+esc(x.unit):'1 matching pack'}</button></div>${amount!==1?`<small>Matching pack: ${esc(t.product||x.name)} · ${esc(t.packLabel||amount+' '+x.unit)}. Save to confirm.</small>`:''}`;}
const SPIRIT_KEYWORDS=['tequila','mezcal','vodka','rum','whiskey','whisky','bourbon','gin','cognac','brandy','liqueur','vermouth','cointreau','triple sec','aperitif','sake','soju','cachaça','cachaca','pisco','absinthe','amaro','campari','aperol','sherry','port'];
const SUPPLY_KEYWORDS=['towel','wipe','cup','ice bag','napkin','straw','coaster','bar mat','trash bag','zip tie','sharpie','glove','apron','tape','tray','bin','bucket','sponge','cloth','paper'];
let inventoryCategory='ingredient';
const keywordIn=(name,keywords)=>keywords.some(k=>new RegExp('(^|[^a-z])'+k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(s|es)?($|[^a-z])').test(name));
function categoryOf(x){if(x.kind==='equipment')return 'equipment';const n=(x.name||'').toLowerCase();if(keywordIn(n,SUPPLY_KEYWORDS))return 'equipment';if(/non-alcoholic|zero-proof|alcohol-free/.test(n))return 'ingredient';return keywordIn(n,SPIRIT_KEYWORDS)?'spirit':'ingredient';}
function inventoryPicker(){const cats=[['ingredient','Ingredients'],['spirit','Spirits'],['equipment','Equipment'],['all','All items']];return `<section class="ops-card"><h3>Pick an item. Count what you have.</h3><p>Choose an ingredient from your mixlists or a standard equipment item. Names and units fill automatically; quantities stay unknown until counted.</p><div class="ops-subtabs" role="tablist" aria-label="Inventory category">${cats.map(([id,label])=>`<button type="button" role="tab" data-cat-tab="${id}" aria-selected="${inventoryCategory===id?'true':'false'}">${esc(label)}</button>`).join('')}</div><label>Find an item<input id="inventory-search" type="search" placeholder="Search tequila, juice, iPad… (searches every category)"></label><div class="picker-results" id="inventory-options">${pickerOptions('')}</div></section>`;}
function pickerOptions(query){const q=query.trim().toLowerCase();const labels={ingredient:'Ingredient',spirit:'Spirit',equipment:'Equipment'};const all=data.inventoryTemplates.map((x,i)=>({...x,index:i}));const scoped=(q||inventoryCategory==='all')?all:all.filter(x=>categoryOf(x)===inventoryCategory);const matches=scoped.filter(x=>(x.name+' '+(x.product||'')).toLowerCase().includes(q));const shown=matches.slice(0,30);return shown.map(x=>`<button type="button" data-pick-item="${x.index}"><strong>${esc(x.name)}</strong><small>${x.kind==='equipment'?'Equipment · auto asset label':esc(x.unit)}${x.product?' · '+esc(x.product):''}${(q||inventoryCategory==='all')?' · '+labels[categoryOf(x)]:''}</small></button>`).join('')+(matches.length>shown.length?`<p class="muted">Showing ${shown.length} of ${matches.length} matches. Keep typing to narrow the list.</p>`:'')||'<p>No match. Use the custom item form below.</p>';}
function inventoryView(){return `<h2>Inventory & equipment</h2><p>Start with counted office stock. Add each machine and iPad separately with its asset label. Receive purchases in the event’s Purchase & pack step to add stock and cost together. Use manual counts only for corrections and record the reason.</p>${state().openingStockZero?'<p class="alert">Opening stock confirmed as zero. Purchase receipts add quantities and cost to inventory.</p>':state().inventory.length?'':'<button data-opening-zero>Confirm empty opening inventory</button>'}${inventoryPicker()}<form id="inventory-form" class="ops-form ops-card"><h3 id="inventory-form-title">Or add a custom item</h3><p id="inventory-pick-note" class="muted"></p><div class="ops-grid">${field('Name / asset tag','name','','text','required maxlength="120"')}<label>Type<select name="kind"><option value="consumable">Ingredient / consumable</option><option value="equipment">Individual equipment asset</option></select></label>${field('Unit (bottle, ml, each)','unit','','text','required maxlength="30"')}${field('Counted quantity (blank = unknown)','quantity','','number','min="0" step="0.001"')}</div><div id="pack-counter" hidden></div><div class="inline-actions"><button type="button" data-inventory-count="0">None in stock</button><button type="button" data-inventory-count="1">Set count to 1</button><button type="button" data-inventory-count="">Count later</button></div>${field('Receipt / count notes','note','','text','maxlength="500"')}<button>Add inventory item</button></form><div class="ops-grid">${state().inventory.map(x=>`<form class="stock-form ops-card ops-form" data-id="${x.id}"><h3>${esc(x.name)}</h3><p>${esc(x.kind)} · ${esc(x.unit)} · ${x.quantity===null?'Not counted':'Counted '+esc(date(x.countedAt))}</p><input name="name" type="hidden" value="${esc(x.name)}">${field('Office quantity','quantity',x.quantity??'','number','min="0" step="0.001"')}${countButtons(x)}${field('Total office stock value USD (at cost)','stockValue',x.stockValueCents==null?'':x.stockValueCents/100,'number','min="0" step="0.01"')}<label>Condition<select name="condition">${['ready','cleaning','charging','repair'].map(v=>`<option ${v===x.condition?'selected':''}>${v}</option>`).join('')}</select></label>${field('Count / condition notes','note',x.note,'text','maxlength="500"')}<p>${state().reservations.filter(r=>r.itemId===x.id&&r.status==='reserved').map(r=>`Reserved ${r.quantity} for ${esc(eventName(r.eventId))} (${esc(date(r.start))})`).join('<br>')||'No reservations'}</p><button>Save count / condition</button></form>`).join('')}</div>`;}
function staffView(){return `<h2>Staff directory</h2><p>Assignments reserve availability across events. Default rate: $50/hour. Mark salaried Barsys team members as “no event labor cost” so their hours never add to an event's cost. Enable crew login explicitly on a saved staff record. Crew see only assigned events; owner financials stay private.</p><form id="staff-form" class="ops-form ops-card"><div class="ops-grid">${field('Name','name','','text','required maxlength="120"')}${field('Role','role','','text','required maxlength="120"')}${field('Hourly rate USD','rate',50,'number','min="0" step="0.01" required')}${check('Barsys team member — no event labor cost','internal',false)}</div><button>Add staff member</button></form><div class="ops-grid">${state().staff.map(x=>`<form class="staff-edit ops-card ops-form" data-id="${x.id}">${field('Name','name',x.name,'text','required maxlength="120"')}${field('Role','role',x.role,'text','maxlength="120"')}${field('Hourly rate USD','rate',x.rateCents/100,'number','min="0" step="0.01" required')}${check('Barsys team member — no event labor cost','internal',!!x.internal)}${field('Barsys Google email','email',x.email||'','email')}${check('Enable assigned-event crew login','crewAccess',x.crewAccess)}${check('Available for new assignments','active',x.active)}<button>Save staff member</button></form>`).join('')}</div>`;}
function activityView(id){return `<div>${[...state().audit].reverse().filter(x=>!id||x.eventId===id).slice(0,100).map(x=>`<p><strong>${esc(x.action)}</strong> · ${esc(x.actor)} · ${esc(date(x.at))}${x.eventId?' · '+esc(eventName(x.eventId)):''}</p>`).join('')||'<p>No operations recorded yet.</p>'}<p class="muted">Most recent 100 actions shown. Full records remain in the database.</p></div>`;}
$('#content').addEventListener('focusin',e=>{const form=e.target.closest('form');if(form&&dirtyForm&&form!==dirtyForm){notify('Save the current form before editing another section.');dirtyForm.querySelector('input:not([type=hidden]),textarea,select')?.focus();}});
$('#content').addEventListener('input',e=>{if(e.target.id==='event-search'||e.target.id==='event-filter'){filterEvents();return;}if(e.target.id==='inventory-search'){$('#inventory-options').innerHTML=pickerOptions(e.target.value);return;}if(e.target.id==='pack-number'){const q=Number(e.target.value),size=Number(e.target.dataset.size);$('#inventory-form [name=quantity]').value=e.target.value===''?'':Math.round(q*size*1000)/1000;}const form=e.target.closest('form');if(form&&dirtyForm&&form!==dirtyForm){if(e.target.type==='checkbox')e.target.checked=e.target.defaultChecked;else if(e.target.tagName==='SELECT')e.target.value=Array.from(e.target.options).find(x=>x.defaultSelected)?.value||e.target.options[0]?.value;else e.target.value=e.target.defaultValue;notify('Save your current form before editing another section.');return;}if(form?.matches('.stock-form')&&e.target.name==='quantity')form.elements.stockValue.value='';if(form?.id==='flow-prep'){const name=e.target.name;if(name.startsWith('ingredients-'))form.elements['confirmed-'+name.slice(12)].checked=false;if(name.startsWith('equipment-'))form.elements['packed-'+name.slice(10)].checked=false;}if(form){dirtyForm=form;$('#discard').hidden=false;notify('Unsaved edits. Save this form before moving to another section.');}});
// Required-field failures inside collapsed sections were invisible; open the section and say which field blocked the save.
$('#content').addEventListener('invalid',e=>{const el=e.target;let d=el.closest('details');while(d){d.open=true;d=d.parentElement?.closest('details');}const label=el.closest('label')?.firstChild?.textContent?.trim()||el.name||'a required field';notify(`Not saved: complete “${label}” first. ${el.validationMessage}`);},true);
$('#content').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,p=Object.fromEntries(new FormData(form)),eventId=selected;try{
 if(form.id==='receipt-form'){const choice=p.item;await command('receive-stock',{eventId:selected,...(choice.startsWith('template:')?{templateIndex:Number(choice.slice(9))}:{itemId:choice}),quantity:Number(p.quantity),costCents:cents(p.cost),paidCents:cents(p.paid),supplier:p.supplier,reference:p.reference,orderId:p.orderId||undefined},form);}
 else if(form.matches('.receipt-payment'))await command('pay-receipt',{eventId:selected,id:form.dataset.id,paidCents:cents(p.paid)},form);
 else if(form.id==='payment-form')await command('payment',{eventId:selected,kind:p.kind,amountCents:cents(p.amount),date:p.date,reference:p.reference},form);
 else if(form.id==='flow-prep'){const plan=planningUpdate(prep.plan,{drinksPerGuest:nullable(p.drinks),bufferPercent:Number(p.buffer),machines:Number(p.machines),menuConfirmed:!!p.menuConfirmed},prep.summary.equipment);for(const [i,r] of plan.recipes.entries()){r.share=Number(p['share-'+i]);r.confirmed=!!p['confirmed-'+i];r.ingredients=p['ingredients-'+i].split('\n').filter(x=>x.trim()).map(line=>{const bits=line.split('|').map(x=>x.trim());if(bits.length!==3)throw Error('Use ingredient name | amount | unit.');return {name:bits[0],amount:Number(bits[1]),unit:bits[2].toLowerCase()};});}for(const q of prep.summary.equipment){const item=plan.equipment[q.id];if(plan.machines===prep.plan.machines){item.quantity=nullable(p['equipment-'+q.id]);item.packed=!!p['packed-'+q.id];}else if(q.minimum===null){item.quantity=nullable(p['equipment-'+q.id]);}}prep=await api('/api/admin/inquiries/'+selected+'/preparation',{method:'PATCH',body:JSON.stringify({version:prep.version,operationsVersion:prep.operationsVersion,plan})});dirtyForm=null;data=await api('/api/admin/operations');render();notify('Preparation saved. '+(prep.impact?.warnings?.join(' ')||'Quantities and packing updated.'));}
 else if(form.id==='event-form')await command('event',{eventId,owner:p.owner,due:iso(p.due),notes:p.notes,revenueCents:cents(p.revenue),targetMargin:Number(p.target),stockUsedCents:cents(p.stockUsed),leftoverCents:cents(p.leftover),staffingConfirmed:!!p.staffingConfirmed,actualHoursConfirmed:!!p.actualHoursConfirmed,expenses:data.expenseCategories.map((_,i)=>({plannedCents:cents(p['planned-'+i]),actualCents:cents(p['actual-'+i]),note:p['note-'+i]}))},form);
 else if(form.matches('.order-form'))await command('order',{eventId,id:form.dataset.id||undefined,supplier:p.supplier,reference:p.reference,status:p.status,amountCents:cents(p.amount),notes:p.notes},form);
 else if(form.id==='inventory-form'||form.matches('.stock-form'))await command('inventory',{id:form.dataset.id,name:p.name,kind:p.kind,unit:p.unit,quantity:nullable(p.quantity),condition:p.condition||'ready',note:p.note,stockValueCents:p.stockValue===undefined?undefined:cents(p.stockValue)},form);
 else if(form.id==='staff-form'||form.matches('.staff-edit'))await command('staff',{id:form.dataset.id,name:p.name,role:p.role,rateCents:cents(p.rate),active:form.id==='staff-form'||!!p.active,email:p.email||'',crewAccess:!!p.crewAccess,internal:!!p.internal},form);
 else if(form.id==='assign-form'||form.matches('.assignment'))await command('assign',{eventId,id:form.dataset.id,staffId:p.staffId,role:p.role,start:iso(p.start),end:iso(p.end),plannedHours:Number(p.plannedHours),actualHours:nullable(p.actualHours??'')},form);
 else if(form.id==='reserve-form')await command('reserve',{eventId,itemId:p.itemId,quantity:Number(p.quantity),start:iso(p.start),end:iso(p.end)},form);
 else if(form.matches('.return-form'))await command('return',{eventId,id:form.dataset.id,returned:Number(p.returned),lost:Number(p.lost),condition:p.condition,note:p.note},form);
 }catch(error){notify(error.message);}});
$('#content').addEventListener('click',async e=>{const b=e.target.closest('button,input[data-task]');if(!b)return;try{
 if(b.hasAttribute('data-cat-tab')){inventoryCategory=b.dataset.catTab;const picker=$('#inventory-options'),search=$('#inventory-search');if(picker)picker.innerHTML=pickerOptions(search?.value||'');document.querySelectorAll('[data-cat-tab]').forEach(t=>{t.setAttribute('aria-selected',t.dataset.catTab===inventoryCategory?'true':'false');});return;}
 if(b.hasAttribute('data-flow-step')){if(!clean())return;viewStep=Number(b.dataset.flowStep);showAllDetails=false;render();}
 if(b.hasAttribute('data-current-step')){if(!clean())return;viewStep=null;render();}
 if(b.hasAttribute('data-show-details')){if(!clean())return;showAllDetails=!showAllDetails;render();}
 if(b.hasAttribute('data-return-preset')){const form=b.closest('form');if(dirtyForm&&dirtyForm!==form){notify('Save the current form first.');return;}const r=state().reservations.find(x=>x.id===form.dataset.id),preset=equipmentReceipt(b.dataset.returnPreset,r.quantity);Object.entries(preset).forEach(([k,v])=>form.elements[k].value=v);form.elements.returned.dispatchEvent(new Event('input',{bubbles:true}));if(preset.lost)form.elements.note.focus();notify('Receipt filled. Check quantities and add any loss or damage notes, then press Receive at office.');}
 if(b.hasAttribute('data-pick-item')){if(!clean())return;const x=data.inventoryTemplates[Number(b.dataset.pickItem)],form=$('#inventory-form');const existing=x.kind==='consumable'&&state().inventory.find(y=>y.kind===x.kind&&y.name.toLowerCase()===x.name.toLowerCase()&&y.unit===x.unit);if(existing){document.querySelector(`.stock-form[data-id="${existing.id}"] [name=quantity]`)?.focus();notify('Already in inventory. Update its existing count below.');return;}form.querySelector('[data-inventory-count="1"]').textContent='1 '+x.unit;let name=x.name;if(x.kind==='equipment'){let n=1;while(state().inventory.some(y=>y.name.toLowerCase()===(name+' #'+String(n).padStart(3,'0')).toLowerCase()))n++;name+=' #'+String(n).padStart(3,'0');}form.elements.name.value=name;form.elements.unit.value=x.unit;form.elements.kind.value=x.kind;form.elements.quantity.value=state().openingStockZero?'0':'';$('#inventory-form-title').textContent='Count '+x.name;$('#inventory-pick-note').textContent=x.kind==='equipment'?'A unique asset label is suggested. Change it to match the label on your device.':('Count in '+x.unit+'. '+(x.product?'Reference product: '+x.product+'. Confirm the pack size matches what you own.':''));const pack=$('#pack-counter');pack.hidden=!x.packAmount;pack.innerHTML=x.packAmount?`<label>Number of matching packs (${esc(x.packLabel||x.packAmount+' '+x.unit)})<input id="pack-number" type="number" min="0" step="0.01" data-size="${x.packAmount}" placeholder="Enter full or partial packs"></label><p class="muted">Converted to ${esc(x.unit)} below. For a different product size, enter the quantity directly.</p>`:'';form.elements.quantity.focus();notify('Item selected. Enter a count, or leave it unknown and save.');}
 if(b.hasAttribute('data-count-adjust')){const form=b.closest('form');if(dirtyForm&&dirtyForm!==form)return;const input=form.elements.quantity;if(input.value===''){notify('Count this item first; unknown stock cannot be incremented.');return;}const item=state().inventory.find(x=>x.id===form.dataset.id),v=Math.round((Number(input.value)+Number(b.dataset.countAdjust))*1000)/1000;if(v<0||(item.kind==='equipment'&&v>1)){notify('Count outside the allowed range.');return;}input.value=v;input.dispatchEvent(new Event('input',{bubbles:true}));}
 if(b.hasAttribute('data-inventory-count')){const form=$('#inventory-form');if(dirtyForm&&dirtyForm!==form)return;form.elements.quantity.value=b.dataset.inventoryCount;const pack=$('#pack-number');if(pack)pack.value='';form.elements.quantity.dispatchEvent(new Event('input',{bubbles:true}));}
 if(b.dataset.openEvent){if(!clean())return;selected=b.dataset.openEvent;showAllDetails=false;viewStep=null;prep=await api('/api/admin/inquiries/'+selected+'/preparation');history.replaceState(null,'','?event='+selected);render();}
 if(b.hasAttribute('data-overview')){if(!clean())return;selected=null;history.replaceState(null,'','/admin/operations.html');render();}
 if(b.hasAttribute('data-task')){if(!clean()){b.checked=!b.checked;return;}await command('task',{eventId:selected,stage:ev().stage,index:Number(b.dataset.task),done:b.checked});}
 if(b.hasAttribute('data-opening-zero'))await command('opening-zero',{});
 for(const action of ['advance','reopen','dispatch','release','unassign'])if(b.hasAttribute('data-'+action))await command(action,{eventId:selected,id:b.dataset[action]});
 if(b.hasAttribute('data-email')){const body=$('#supplier-draft').value;location.href='mailto:vpagan@astorwines.com?subject='+encodeURIComponent('Quote request — '+eventName(selected))+'&body='+encodeURIComponent(body);}
 if(b.hasAttribute('data-download-draft')){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([$('#supplier-draft').value],{type:'text/plain'}));a.href=url;a.download='Astor-quote-draft.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 }catch(error){notify(error.message);}});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(!clean())return;tab=b.dataset.tab;render();});$('#refresh').onclick=load;$('#discard').onclick=()=>{dirtyForm=null;load();};window.addEventListener('beforeunload',e=>{if(dirtyForm){e.preventDefault();e.returnValue='';}});load();

function receiptForm(e){const needs=purchaseNeeds(prep?.summary.costs.rows||[],state(),selected);return `<h3>Buy what is missing</h3><p>${usd(needs.knownPurchaseCents)} known whole-pack estimate after counted stock and allocations. ${prep?.summary.complete&&!needs.unresolved.length?'Review current supplier prices before ordering.':'Incomplete: confirm recipes, counts, prices and yields.'}</p><ul>${needs.purchases.map(x=>`<li>${esc(x.product)} · ${x.packs} packs · ${usd(x.purchaseCents)}</li>`).join('')}${needs.unresolved.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Receive purchased stock</h3><p>Use invoice amounts, not catalog estimates. Quantities use the displayed stock unit (for example ml). Each receipt adds stock once and records its cost. Supplier balances remain separate from event consumption.</p><form id="receipt-form" class="ops-form ops-card"><label>Item<select name="item" required><option value="">Choose existing stock or a catalog item</option>${state().inventory.map(x=>`<option value="${x.id}">${esc(x.name)} · ${esc(x.unit)}</option>`).join('')}${data.inventoryTemplates.map((x,i)=>`<option value="template:${i}">New / match: ${esc(x.name)} · ${esc(x.unit)}</option>`).join('')}</select></label><label>Related supplier order<select name="orderId"><option value="">No order linked</option>${(e.orders||[]).map(x=>`<option value="${x.id}">${esc(x.supplier)} · ${esc(x.reference)}</option>`).join('')}</select></label><div class="ops-grid">${field('Supplier','supplier','','text','required maxlength="200"')}${field('Invoice / delivery reference (unique per item)','reference','','text','required maxlength="200"')}${field('Quantity received in item units','quantity','','number','min="0.001" step="0.001" required')}${field('Total invoice cost for this item, USD','cost','','number','min="0" step="0.01" required')}${field('Amount already paid for this item, USD','paid','','number','min="0" step="0.01" required')}</div><button>Receive stock & record cost</button></form><details><summary>Received stock ledger</summary>${(state().receipts||[]).filter(r=>r.eventId===selected).map(r=>`<p>${esc(r.reference)} · ${esc(state().inventory.find(x=>x.id===r.itemId)?.name)} · ${r.quantity} received · cost ${usd(r.costCents)} · paid ${usd(r.paidCents)}</p>${r.paidCents<r.costCents?`<form class="receipt-payment ops-form" data-id="${r.id}">${field('Updated total paid USD','paid',r.paidCents/100,'number',`min="${r.paidCents/100}" max="${r.costCents/100}" step="0.01" required`)}<button>Record supplier payment</button></form>`:''}`).join('')||'<p>No receipts recorded.</p>'}</details>`;}
function paymentForm(e,f){const p=f?.payments||{collectedCents:0,balanceCents:e.revenueCents,status:'Unpaid'};return `<details><summary>Client payments · ${esc(p.status)}</summary><p>Collected ${usd(p.collectedCents)} · Balance ${usd(p.balanceCents)}. Record money received outside this dashboard; this does not charge a card or send an invoice. Accepted-proposal balances use the gross client total including tax. Other events use the entered revenue amount; accept a proposal to track tax separately.</p><form id="payment-form" class="ops-form"><label>Type<select name="kind"><option value="deposit">Deposit received</option><option value="payment">Payment received</option><option value="refund">Refund paid</option></select></label>${field('Amount USD','amount','','number','min="0.01" step="0.01" required')}${field('Payment date','date','','date','required')}${field('Bank / payment reference','reference','','text','maxlength="200" required')}<button>Record payment</button></form>${(e.payments||[]).map(x=>`<p>${esc(x.date)} · ${esc(x.kind)} · ${usd(x.amountCents)} · ${esc(x.reference)}</p>`).join('')}</details>`;}
